@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @allTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @allTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" @bind="searchQuery" @bind:event="oninput" placeholder="Search tasks by title..." class="form-control" />
    </div>

    <!-- Kanban Columns -->
    <div class="kanban-board">
        @foreach (var column in columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            <div class="kanban-column">
                <div class="column-header">
                    <h3>@column <span class="badge">@tasks.Count</span></h3>
                </div>
                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (GetColumnIndex(column) > 0)
                                {
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => MoveTask(task, -1)" disabled="@isMoving">← Move Left</button>
                                }
                                @if (GetColumnIndex(column) < columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => MoveTask(task, 1)" disabled="@isMoving">Move Right →</button>
                                }
                            </div>
                        </div>
                    }
                </div>
                <div class="column-footer">
                    @if (activeFormColumn == column)
                    {
                        <div class="add-task-form">
                            <input type="text" @bind="newTitle" placeholder="Title" class="form-control form-control-sm mb-1" />
                            <input type="text" @bind="newAssignee" placeholder="Assignee" class="form-control form-control-sm mb-1" />
                            <select @bind="newPriority" class="form-select form-select-sm mb-1">
                                <option value="High">High</option>
                                <option value="Medium">Medium</option>
                                <option value="Low">Low</option>
                            </select>
                            <input type="date" @bind="newDueDate" class="form-control form-control-sm mb-1" />
                            <div class="form-buttons">
                                <button class="btn btn-sm btn-primary" @onclick="() => SaveTask(column)" disabled="@isSaving">Save</button>
                                <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                            </div>
                        </div>
                    }
                    else
                    {
                        <button class="btn btn-sm btn-outline-primary add-task-btn" @onclick="() => ShowAddForm(column)">+ Add Task</button>
                    }
                </div>
            </div>
        }
    </div>
}

<style>
    .stats-bar {
        display: flex;
        gap: 1.5rem;
        padding: 0.75rem 1rem;
        background: #f8f9fa;
        border-radius: 0.5rem;
        margin-bottom: 1rem;
        flex-wrap: wrap;
    }
    .stat-item { font-size: 0.9rem; }
    .stat-overdue { color: #dc3545; }
    .search-bar { margin-bottom: 1rem; max-width: 400px; }
    .kanban-board {
        display: flex;
        gap: 1rem;
        align-items: flex-start;
    }
    .kanban-column {
        flex: 1;
        background: #f1f3f5;
        border-radius: 0.5rem;
        padding: 0.75rem;
        min-width: 250px;
        display: flex;
        flex-direction: column;
    }
    .column-header h3 {
        font-size: 1rem;
        margin: 0 0 0.5rem;
    }
    .column-header .badge {
        background: #6c757d;
        color: #fff;
        border-radius: 10px;
        padding: 0.15rem 0.5rem;
        font-size: 0.75rem;
    }
    .column-body { display: flex; flex-direction: column; gap: 0.5rem; min-height: 50px; }
    .task-card {
        background: #fff;
        border: 1px solid #dee2e6;
        border-radius: 0.4rem;
        padding: 0.6rem;
    }
    .task-title { font-weight: 600; margin-bottom: 0.25rem; }
    .task-assignee { font-size: 0.8rem; color: #6c757d; margin-bottom: 0.25rem; }
    .task-due { font-size: 0.8rem; color: #495057; margin-top: 0.25rem; }
    .task-actions { margin-top: 0.4rem; display: flex; gap: 0.25rem; }
    .priority-badge {
        display: inline-block;
        padding: 0.1rem 0.4rem;
        border-radius: 0.25rem;
        font-size: 0.7rem;
        font-weight: 600;
        color: #fff;
    }
    .priority-high { background-color: #dc3545; }
    .priority-medium { background-color: #ffc107; color: #212529; }
    .priority-low { background-color: #28a745; }
    .column-footer { margin-top: 0.75rem; }
    .add-task-form { background: #fff; padding: 0.5rem; border-radius: 0.4rem; border: 1px solid #dee2e6; }
    .form-buttons { display: flex; gap: 0.5rem; }
    .add-task-btn { width: 100%; }
</style>

@code {
    private readonly string[] columns = { "To Do", "In Progress", "Done" };

    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private bool isMoving;
    private bool isSaving;
    private string? errorMessage;
    private string searchQuery = string.Empty;

    // Add task form state
    private string? activeFormColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrWhiteSpace(searchQuery) || t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private int GetColumnIndex(string column) => Array.IndexOf(columns, column);

    private async Task MoveTask(TaskItem task, int direction)
    {
        var currentIndex = GetColumnIndex(task.Status);
        var newIndex = currentIndex + direction;
        if (newIndex < 0 || newIndex >= columns.Length) return;

        var newStatus = columns[newIndex];
        isMoving = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Update local state
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            isMoving = false;
        }
    }

    private void ShowAddForm(string column)
    {
        activeFormColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => activeFormColumn = null;

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(newTitle)) return;

        isSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            // The service creates tasks; if status doesn't match column, update it
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            allTasks.Add(created);
            activeFormColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }
}

